package com.greenpulse.service;
import com.greenpulse.domain.*;import com.greenpulse.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;
@Service
public class RecommendationService {
 private final RecommendationRepository recommendations;private final ReadingService readings;private final BuildingRepository buildings;private final CurrentUser current;
 public RecommendationService(RecommendationRepository recommendations,ReadingService readings,BuildingRepository buildings,CurrentUser current){this.recommendations=recommendations;this.readings=readings;this.buildings=buildings;this.current=current;}
 public List<Recommendation> list(){var u=current.get();return recommendations.scoped(current.isSuper(u),current.org(u));}
 @Transactional public Map<String,Object> generate(Long buildingId){var rows=readings.byBuilding(buildingId);var building=rows.stream().findFirst().map(EnergyReading::getBuilding).orElseGet(()->{var u=current.get();return buildings.findScoped(buildingId,current.isSuper(u),current.org(u)).orElseThrow(()->new NoSuchElementException("Building not found"));});if(rows.size()<14)return Map.of("created",0,"message","At least 14 readings are required for a month-over-month pattern check");var sorted=rows.stream().sorted(Comparator.comparing(EnergyReading::getReadingDate)).toList();var prior=mean(sorted.subList(sorted.size()-14,sorted.size()-7));var recent=mean(sorted.subList(sorted.size()-7,sorted.size()));BigDecimal change=prior.signum()==0?BigDecimal.ZERO:recent.subtract(prior).divide(prior,4,RoundingMode.HALF_UP);int created=0;if(change.compareTo(new BigDecimal("0.15"))>0){String title="Consumption increased over the prior week";if(!recommendations.existsByBuildingIdAndTitleAndStatus(buildingId,title,"OPEN")){var r=new Recommendation();r.setBuilding(building);r.setTitle(title);r.setRecommendationType("CONSUMPTION_TREND");r.setPriority(change.compareTo(new BigDecimal("0.30"))>0?"HIGH":"MEDIUM");r.setEstimatedSavingKwh(recent.multiply(new BigDecimal("0.05")).setScale(3,RoundingMode.HALF_UP));r.setDescription(String.format("The latest 7 observed reading average is %.1f%% above the previous 7 observations. Review schedules and equipment. Potential saving estimate assumes a 5%% reduction of the latest daily average; savings are not guaranteed.",change.multiply(new BigDecimal("100"))));recommendations.save(r);created++;}}return Map.of("created",created,"message",created==0?"No new recommendation rules matched":"Recommendation generated from recorded readings","recentAverageKwh",recent,"previousAverageKwh",prior);}
 @Transactional public Recommendation status(Long id,String status){if(!Set.of("OPEN","IN_PROGRESS","COMPLETED","DISMISSED").contains(status))throw new IllegalArgumentException("Unsupported recommendation status");var u=current.get();var r=recommendations.scoped(current.isSuper(u),current.org(u)).stream().filter(x->x.getId().equals(id)).findFirst().orElseThrow(()->new NoSuchElementException("Recommendation not found"));r.setStatus(status);return recommendations.save(r);}
 private BigDecimal mean(List<EnergyReading> values){return values.stream().map(EnergyReading::getEnergyConsumedKwh).reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(values.size()),3,RoundingMode.HALF_UP);}
}
